#!/usr/bin/env python3
"""Заключение пояснительной записки в оформлении образца (заголовок «ЗАКЛЮЧЕНИЕ» по центру без номера).
Использование: python3 build_z.py [выход.docx]
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.shared import Cm
from build_2 import Doc, KURS


def build(out):
    b = Doc(chap=0)
    h = b._p('Heading 1')
    h.alignment = WD_ALIGN_PARAGRAPH.CENTER
    h.paragraph_format.first_line_indent = Cm(0)
    h.paragraph_format.left_indent = Cm(0)
    h.add_run('ЗАКЛЮЧЕНИЕ')
    b.empty()
    b.text('В ходе выполнения курсового проекта разработано программное средство дистанционного банковского обслуживания физических лиц «ТалерБанк». Поставленная цель, автоматизация процессов дистанционного обслуживания для сокращения времени выполнения операций и снижения нагрузки на сотрудников банка, достигнута, а все задачи, сформулированные во введении, решены.')
    b.text('В первом разделе проанализирована предметная область дистанционного банковского обслуживания и рассмотрены системы интернет-банкинга действующих банков Республики Беларусь. Построены функциональная модель процесса кредитования в нотации IDEF0, информационная модель базы данных и UML-модели представления программного средства, сформулированы бизнес-правила и спецификация функциональных требований для каждой роли пользователя.')
    b.text('Во втором разделе обоснован выбор технологий и спроектирована архитектура программного средства. Серверная часть написана на JavaScript с использованием платформы Node.js и фреймворка Express и построена по шаблону MVC, а код сгруппирован по семнадцати предметным модулям, в каждом из которых маршруты, контроллеры, сервисы бизнес-логики и модели доступа к данным разделены по слоям. Данные хранятся в реляционной базе MySQL со ссылочной целостностью, а интерфейс построен на HTML5, CSS3 и JavaScript без сторонних фреймворков с единственной таблицей стилей для всего приложения.')
    b.text('Ключевым проектным решением стал учёт всех денежных операций по принципу двойной записи. Остаток каждого счёта рассчитывается по проводкам, суммы хранятся в копейках целыми числами, каждая операция выполняется в одной транзакции с блокировкой строк и защитой от повторного проведения, а проводки и журнал аудита защищены от изменения триггерами базы данных. Разработаны алгоритмы перевода средств с конвертацией и подтверждением кодом, начисления процентов по вкладам с учётом високосного года, построения аннуитетного и дифференцированного графиков платежей, а также оценки кредитоспособности логистической регрессией с ограничением долговой нагрузки 40 % по требованиям Национального банка.')
    b.text('Программное средство поддерживает шесть категорий пользователей: гостя, клиента, операциониста, кредитного специалиста, специалиста по финансовому мониторингу и администратора. Права доступа задаются набором разрешений роли и проверяются на сервере для каждого запроса. Реализовано более пятнадцати бизнес-операций, в том числе открытие счетов в пяти валютах, переводы между своими счетами, клиентам банка и в другие банки через клиринг, оплата услуг по каталогу с шаблонами и автоплатежами, оформление и досрочное закрытие вкладов, выдача и погашение кредитов, выпуск и блокировка карт, выписки и квитанции в формате PDF, контроль подозрительных операций, проверка анкет, кассовые операции и закрытие операционного дня.')
    b.text('Защита данных построена в несколько уровней. Пароли хранятся в виде хэшей bcrypt, вход защищён ограничением числа попыток и двухфакторной аутентификацией по стандарту TOTP, запросы защищены от подделки токеном CSRF, паспортные данные и секреты шифруются алгоритмом AES-256-GCM, а резервные копии базы данных создаются по расписанию и также шифруются.')
    b.text('В третьем разделе проведено тестирование программного средства. Программные тесты проверяют сервисы двойной записи, переводов, вкладов и кредитов на отдельной тестовой базе данных, а тесты бизнес-логики в интерфейсе подтверждают, что ошибки пользователя и исключительные ситуации обнаруживаются до изменения данных и сопровождаются понятными сообщениями. Все тесты завершились успешно, а дефекты, найденные при тестировании, исправлены. В четвёртом разделе приведены руководство по установке программного средства и руководство пользователя для каждой роли.')
    b.text('Практическая значимость работы состоит в том, что программное средство переносит основные операции физического лица с банком в дистанционный канал. Клиент открывает счета, переводит деньги, оплачивает услуги, оформляет вклады и кредиты без посещения отделения, решение по типовой кредитной заявке принимается автоматически сразу после её подачи, а сотрудники банка работают только с операциями, которые требуют их решения.')
    b.text('Дальнейшее развитие программного средства возможно в нескольких направлениях:')
    b.bullets([
        'разработка мобильного приложения, работающего с тем же программным интерфейсом',
        'подключение межбанковской системы идентификации для регистрации клиентов без проверки анкеты сотрудником',
        'доставка кодов подтверждения по SMS и push-уведомлениями наряду с электронной почтой',
        'поддержка межбанковских переводов в иностранной валюте и обмен платёжными сообщениями с реальной системой межбанковских расчётов',
        'дообучение модели оценки кредитоспособности на истории погашения выданных кредитов',
    ])
    b.save(out)


if __name__ == '__main__':
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(KURS, 'zaklyuchenie.docx')
    build(out)
    print(out)
